sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var Constants = x_gegis_ins_policy.Constants;
    var APPLIED = Constants.CHOICE.DISPOSITION.APPLIED;

    // Same allow-list as "UW Guideline trigger on extraction confirmed" - see
    // that rule's header comment for the bucketing assumption.
    var GUIDELINE_ALLOW_LIST = ['total_insured_value', 'line_of_business', 'construction_type'];

    var changedField = String(current.getValue('changed_field'));
    if (GUIDELINE_ALLOW_LIST.indexOf(changedField) == -1)
        return; // not a guideline-relevant column - nothing to re-score

    // extraction_field is a plain string column carrying the extraction_field
    // sys_id (not a declared reference on this table) - resolve it manually.
    var fieldGr = new GlideRecord('x_gegis_ins_policy_extraction_field');
    if (!fieldGr.get(String(current.getValue('extraction_field'))))
        return;

    var extractionGr = new GlideRecord('x_gegis_ins_policy_extraction');
    if (!extractionGr.get(String(fieldGr.getValue('extraction'))))
        return;
    if (String(extractionGr.getValue('disposition')) != APPLIED)
        return; // not confirmed yet - "UW Guideline trigger on extraction confirmed" will fire when it is

    var oldSnapshot = {}, newSnapshot = {};
    oldSnapshot[changedField] = String(current.getValue('old_value'));
    newSnapshot[changedField] = String(current.getValue('new_value'));

    var changedFields = new UWFieldSnapshotDiff().diff(oldSnapshot, newSnapshot, GUIDELINE_ALLOW_LIST);
    if (!changedFields.length)
        return; // old_value === new_value - nothing actually changed

    var triggerReasonId = new UWTriggerReasonResolver().resolve({
        consumer: 'uw_guideline',
        changedFields: changedFields,
        isManualCorrection: true
    });
    if (!triggerReasonId)
        return; // resolver already gs.error'd with full context

    var submissionId = String(extractionGr.getValue('submission'));
    var versionService = new UWGuidelineVersionService();
    var lines = new GlideRecord('x_gegis_ins_policy_submission_line');
    lines.addQuery('submission', submissionId);
    lines.query();
    var created = 0;
    while (lines.next()) {
        if (versionService.createNextVersion(lines.getUniqueValue(), extractionGr.getUniqueValue(), triggerReasonId))
            created++;
    }
    if (!created)
        gs.error('[UW Guideline trigger on manual correction] no submission_line rows found for submission ' +
            submissionId + ' - no uw_guideline_version created for audit ' + current.getUniqueValue());

})(current, previous);
